package main_test

import (
	"encoding/json/v2"
	"os"
	"testing"
)

func TestPostgresDollarQuotedBoundaries(t *testing.T) {
	data, err := os.ReadFile("testdata/dollar-strings.json")
	if err != nil {
		t.Fatal(err)
		return
	}
	var cases []continuedStringCase
	if err := json.Unmarshal(data, &cases); err != nil {
		t.Fatal(err)
		return
	}
	if len(cases) != 14 {
		t.Fatalf("dollar-string cases = %d; want 14", len(cases))
		return
	}
	for _, tc := range cases {
		t.Run(tc.Name, func(t *testing.T) {
			checkContinuedString(t, tc)
		})
	}
}

package main_test

import (
	"context"
	"encoding/json/v2"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
	"time"

	sqlcgen "github.com/gosuda/spira/cmd/sqlc-gen-spira"
)

func TestGeneratedQueryConstants(t *testing.T) {
	data, err := os.ReadFile("testdata/query-constant-values.json")
	if err != nil {
		t.Fatal(err)
		return
	}
	var cases []continuedStringCase
	if err := json.Unmarshal(data, &cases); err != nil {
		t.Fatal(err)
		return
	}
	if len(cases) != 8 {
		t.Fatalf("query constant cases = %d; want 8", len(cases))
		return
	}
	work := t.TempDir()
	expected := make([]sqlcLiteralExpectation, 0, len(cases))
	for _, tc := range cases {
		writeQueryConstantPackage(t, work, tc)
		expected = append(expected, sqlcLiteralExpectation{Name: tc.Name, Text: tc.SQL})
	}
	ctx, cancel := context.WithTimeout(t.Context(), 5*time.Minute)
	defer cancel()
	if err := checkCompiledSQLcQueries(t, ctx, work, expected); err != nil {
		t.Fatal(err)
	}
}

func writeQueryConstantPackage(t *testing.T, work string, tc continuedStringCase) {
	t.Helper()
	req := loadRequest(t, "postgresql")
	req.PluginOptions = pluginOptions(t, map[string]any{
		"package": "generated",
		"tables": map[string]any{
			"items": map[string]any{"type": "Item", "key": "id", "key_type": "ItemID", "version": "version"},
		},
	})
	req.Queries = []sqlcgen.Query{{
		Name: "ContinueItem", Cmd: ":exec", Filename: "queries.sql", Text: tc.SQL,
	}}
	_, files, err := sqlcgen.Generate(req)
	if err != nil {
		t.Fatal(err)
		return
	}
	if len(files) != 2 || files[0].Name != "models.sql.lgo" || files[1].Name != "queries.sql.lgo" {
		t.Fatal("generated runtime fixture must contain exactly models.sql.lgo and queries.sql.lgo")
		return
	}
	dir := filepath.Join(work, tc.Name, "generated")
	if err := os.MkdirAll(dir, 0o755); err != nil {
		t.Fatal(err)
		return
	}
	for _, file := range files {
		if err := os.WriteFile(filepath.Join(dir, file.Name), file.Contents, 0o644); err != nil {
			t.Fatal(err)
			return
		}
	}
}

func checkCompiledSQLcQueries(t *testing.T, ctx context.Context, dir string, expected []sqlcLiteralExpectation) error {
	t.Helper()
	root := filepath.Abs(filepath.Join("..", ".."))?
	configureSQLcSQLite(ctx, root, dir)?
	writeCompiledQueryFixture(dir, expected)?
	cmd := exec.CommandContext(ctx, "logos", "test", "-count=1", "-v", ".")
	cmd.Dir = dir
	err := runSQLcSQLiteCommand(cmd)
	data, readErr := os.ReadFile(filepath.Join(dir, "observed.json"))
	if readErr != nil {
		if err != nil {
			return err
		}
		return readErr
	}
	t.Logf("COMPILED_SQLC_QUERY_VALUES %s", data)
	return err
}

func writeCompiledQueryFixture(dir string, expected []sqlcLiteralExpectation) error {
	template := os.ReadFile("testdata/query_constants_test.lgo.tmpl")?
	var imports strings.Builder
	var values strings.Builder
	for i, tc := range expected {
		fmt.Fprintf(&imports, "\tq%d %q\n", i, "example.com/spira-sqlc-runtime/"+tc.Name+"/generated")
		fmt.Fprintf(&values, "\t\t%q: q%d.ContinueItemQuery,\n", tc.Name, i)
	}
	source := strings.Replace(string(template), "// QUERY_IMPORTS", imports.String(), 1)
	source = strings.Replace(source, "// QUERY_VALUES", values.String(), 1)
	os.WriteFile(filepath.Join(dir, "query_constants_test.lgo"), []byte(source), 0o644)?
	data := json.Marshal(expected)?
	return os.WriteFile(filepath.Join(dir, "expected.json"), data, 0o644)
}

package queryproof_test

import (
	"encoding/json/v2"
	"os"
	"testing"

// QUERY_IMPORTS
)

type queryExpectation struct {
	Name string `json:"name"`
	Text string `json:"text"`
}

func TestCompiledQueryValues(t *testing.T) {
	data, err := os.ReadFile("expected.json")
	if err != nil {
		t.Fatal(err)
		return
	}
	var expected []queryExpectation
	if err := json.Unmarshal(data, &expected); err != nil {
		t.Fatal(err)
		return
	}
	actual := compiledQueryValues()
	encoded, err := json.Marshal(actual)
	if err != nil {
		t.Fatal(err)
		return
	}
	if err := os.WriteFile("observed.json", encoded, 0o644); err != nil {
		t.Fatal(err)
		return
	}
	if len(actual) != len(expected) {
		t.Fatalf("compiled queries = %d; want %d", len(actual), len(expected))
		return
	}
	seen := map[string]bool{}
	for _, want := range expected {
		t.Run(want.Name, func(t *testing.T) {
			if seen[want.Name] ?? false {
				t.Fatalf("duplicate expected query %q", want.Name)
				return
			}
			seen[want.Name] = true
			got, ok := actual[want.Name]
			if !ok || got != want.Text {
				t.Errorf("compiled query %s = %q; want exact bytes %q", want.Name, got, want.Text)
			}
		})
	}
}

func compiledQueryValues() map[string]string {
	return map[string]string{
// QUERY_VALUES
	}
}

package main_test

import (
	"context"
	"encoding/json/v2"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
	"testing"
	"time"
)

type sqlcLiteralExpectation struct {
	Name      string `json:"name"`
	Text      string `json:"text"`
	SQLcError string `json:"sqlc_error"`
}

type sqlcLiteralCase struct {
	Input    continuedStringCase
	Expected sqlcLiteralExpectation
}

func TestSQLcPostgresLiteralPipeline(t *testing.T) {
	root, err := filepath.Abs(filepath.Join("..", ".."))
	if err != nil {
		t.Fatal(err)
		return
	}
	cases, err := readSQLcLiteralInputs()
	if err != nil {
		t.Fatal(err)
		return
	}
	data, err := os.ReadFile("testdata/sqlc-literal-pipeline.json")
	if err != nil {
		t.Fatal(err)
		return
	}
	var expected []sqlcLiteralExpectation
	if err := json.Unmarshal(data, &expected); err != nil {
		t.Fatal(err)
		return
	}
	if len(cases) != 40 || len(expected) != len(cases) {
		t.Fatalf("pipeline inputs/expectations = %d/%d; want 40/40", len(cases), len(expected))
		return
	}
	work := t.TempDir()
	ctx, cancel := context.WithTimeout(t.Context(), 5*time.Minute)
	defer cancel()
	build := exec.CommandContext(ctx, "logos", "build", "-o", filepath.Join(work, "sqlc-gen-spira"), "./cmd/sqlc-gen-spira")
	build.Dir = root
	if err := runSQLcSQLiteCommand(build); err != nil {
		t.Fatal(err)
		return
	}
	var compiled []sqlcLiteralExpectation
	for i, tc := range cases {
		want := expected[i]
		if tc.Allow && want.SQLcError == "" {
			compiled = append(compiled, want)
		}
		if tc.Name != want.Name {
			t.Fatalf("pipeline fixture %d = %q; want %q", i, tc.Name, want.Name)
			return
		}
		t.Run(tc.Name, func(t *testing.T) {
			if err := exerciseSQLcPostgresLiteral(ctx, root, filepath.Join(work, tc.Name), sqlcLiteralCase{Input: tc, Expected: want}); err != nil {
				t.Fatal(err)
			}
		})
	}
	if !t.Failed() {
		if err := checkCompiledSQLcQueries(t, ctx, work, compiled); err != nil {
			t.Fatal(err)
		}
	}
}

func readSQLcLiteralInputs() ([]continuedStringCase, error) {
	var cases []continuedStringCase
	for _, name := range []string{"continued-strings.json", "typed-literals.json", "dollar-strings.json"} {
		data := os.ReadFile(filepath.Join("testdata", name))?
		var part []continuedStringCase
		json.Unmarshal(data, &part)?
		cases = append(cases, part...)
	}
	return cases, nil
}

func exerciseSQLcPostgresLiteral(ctx context.Context, root string, dir string, fixture sqlcLiteralCase) error {
	tc, want := fixture.Input, fixture.Expected
	os.Mkdir(dir, 0o755)?
	schema := os.ReadFile(filepath.Join(root, "cmd", "sqlc-gen-spira", "testdata", "literal-schema.sql"))?
	os.WriteFile(filepath.Join(dir, "schema.sql"), schema, 0o644)?
	os.WriteFile(filepath.Join(dir, "queries.sql"), []byte("-- name: ContinueItem :exec\n"+tc.SQL+"\n"), 0o644)?
	config := fmt.Sprintf(`version: "2"
plugins:
  - name: spira
    process:
      cmd: %s
      format: json
sql:
  - engine: postgresql
    schema: schema.sql
    queries: queries.sql
    codegen:
      - plugin: spira
        out: generated
        options:
          package: generated
          tables:
            items: {type: Item, key: id, key_type: ItemID, version: version}
`, strconv.Quote(filepath.Join(filepath.Dir(dir), "sqlc-gen-spira")))
	os.WriteFile(filepath.Join(dir, "sqlc.yaml"), []byte(config), 0o644)?
	cmd := exec.CommandContext(ctx, "go", "-C", filepath.Join(root, "tools"), "tool", "sqlc", "generate", "-f", filepath.Join(dir, "sqlc.yaml"))
	cmd.Dir = root
	err := runSQLcSQLiteCommand(cmd)
	files := filepath.Glob(filepath.Join(dir, "generated", "*.lgo"))?
	if want.SQLcError != "" {
		return checkSQLcLiteralRefusal(ctx, err, want.SQLcError, files)
	}
	if !tc.Allow {
		return checkSQLcLiteralRefusal(ctx, err, "ContinueItem: writes versioned table items without version", files)
	}
	if err != nil {
		return err
	}
	if len(files) != 2 {
		return fmt.Errorf("sqlc generated %d source files; want 2", len(files))
	}
	generated := os.ReadFile(filepath.Join(dir, "generated", "queries.sql.lgo"))?
	if strings.Count(string(generated), "const ContinueItemQuery = ") != 1 {
		return errors.New("generated source must declare exactly one ContinueItemQuery")
	}
	return nil
}

func checkSQLcLiteralRefusal(ctx context.Context, err error, diagnostic string, files []string) error {
	if err == nil {
		return errors.New("sqlc accepted a frozen refusal case")
	}
	exit, exited := errors.AsType[*exec.ExitError](err)
	if !exited || exit.ExitCode() != 1 || ctx.Err() != nil {
		return fmt.Errorf("sqlc did not complete the expected refusal: %w", err)
	}
	if !strings.Contains(err.Error(), diagnostic) {
		return fmt.Errorf("sqlc refusal did not contain %q: %w", diagnostic, err)
	}
	if len(files) != 0 {
		return fmt.Errorf("sqlc emitted %d source files after a refusal", len(files))
	}
	return nil
}

